var s=`0969-galbi`;var a=`world-0969`;var n=`KR`;var t=`east-asia`;var r=4;var o=145;var g={en:`Galbi`,ua:`Кальбі`};var l={en:`Galbi is a South Korea dish made with beef short ribs, asian pear, light soy sauce, garlic. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кальбі, страва кухні країни Південна Корея. Основні складники: короткі яловичі ребра, азійська груша, світлий соєвий соус, часник. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 120 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 120 хвилин.`,t:[`marinating`],m:120,i:[[`beef-short-ribs`,950,`g`],[`asian-pear`,1,`pcs`],[`light-soy-sauce`,95,`ml`],[`brown-sugar`,35,`g`],[`garlic`,5,`clove`],[`toasted-sesame-oil`,25,`ml`]]},{en:`Grill over medium-high heat for about 22 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 22 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:22,i:[[`canola-oil`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,45,`g`],[`white-sesame-seeds`,20,`g`]]}];var u={slug:s,id:a,country:`KR`,region:t,servings:4,minutes:145,title:g,text:l,steps:h};export{n as country,u as default,a as id,o as minutes,t as region,r as servings,s as slug,h as steps,l as text,g as title};